27		"strix-halo-vulkan/safetensors"
28		"strix-halo-vulkan/zimage/qwen"
29	)
30	
31	// Dim is the model's embedding width, and the largest vector it produces.
32	// The card supports 32..1024 by truncating and renormalising (MRL); Truncate
33	// is that operation.
34	const Dim = 1024
35	
36	// Model is the CPU reference: the oracle the Vulkan path is debugged
37	// against, not the fast path. Weights are float32, 2.38 GB.
38	type Model struct {
39		Cfg  *qwen.Config
40		Enc  *qwen.Model   // embedding table and all NumLayers decoder layers
41		Norm *qwen.RMSNorm // the final norm, which the text encoder never runs
42		Tok  *Tokenizer
43	}
44	
45	// Load reads a checkpoint directory -- models/Qwen3-Embedding-0.6B -- with
46	// its tokenizer.
47	func Load(dir string) (*Model, error) {
48		cfg, err := LoadConfig(dir)
49		if err != nil {
50			return nil, err
51		}
52		enc, err := qwen.LoadWith(dir, cfg, cfg.NumLayers)
53		if err != nil {
54			return nil, err
55		}
56		set, err := safetensors.OpenSet(dir)
57		if err != nil {
58			return nil, err
59		}
60		defer set.Close()
61		norm, err := LoadFinalNorm(set, cfg)
62		if err != nil {
63			return nil, err
64		}
65		tok, err := LoadTokenizer(dir)
66		if err != nil {
67			return nil, err
68		}
69		return &Model{Cfg: cfg, Enc: enc, Norm: norm, Tok: tok}, nil
70	}
