72	// Hidden runs the whole stack over a token sequence and returns the normed
73	// hidden states, [tokens, HiddenSize] -- transformers'
74	// `last_hidden_state`. tr may be nil.
75	func (m *Model) Hidden(ids []int32, tr qwen.Trace) (*qwen.Mat, error) {
76		x, err := m.Enc.Forward(ids, tr)
77		if err != nil {
78			return nil, err
79		}
80		out, err := m.Norm.Apply(x)
81		if err != nil {
82			return nil, fmt.Errorf("embed: final norm: %w", err)
83		}
84		if tr != nil {
85			tr["final"] = out.Clone()
86		}
87		return out, nil
88	}
