91	// carry the appended end-of-text token; Tokenizer.Encode puts it there.
92	func (m *Model) EmbedIDs(ids []int32) ([]float32, error) {
93		h, err := m.Hidden(ids, nil)
94		if err != nil {
95			return nil, err
96		}
97		return Normalize(Pool(h)), nil
98	}
99	
100	// Embed is the whole thing: text to a unit vector.
101	func (m *Model) Embed(text string) ([]float32, error) {
102		ids, err := m.Tok.Encode(text)
103		if err != nil {
104			return nil, err
105		}
106		return m.EmbedIDs(ids)
107	}
