109	// Pool takes the last row, which is `pooling_mode_lasttoken` over a sequence
110	// that is not left-padded. Nothing in this repository pads: a Go caller runs
111	// one sequence at a time, and the reference dump measures that a right-padded
112	// batch gives a real token the same hidden state to 2.5e-05.
113	func Pool(h *qwen.Mat) []float32 {
114		return append([]float32(nil), h.Row(h.Rows-1)...)
115	}
