117	// Normalize scales a vector to unit length in place and returns it. A zero
118	// vector is left alone rather than turned into NaNs.
119	func Normalize(v []float32) []float32 {
120		var sum float64
121		for _, x := range v {
122			sum += float64(x) * float64(x)
123		}
124		if sum == 0 {
125			return v
126		}
127		scale := float32(1 / math.Sqrt(sum))
128		for i := range v {
129			v[i] *= scale
130		}
131		return v
132	}
