135	// renormalise. The card supports 32..1024 this way. d <= 0 or d >= len(v)
136	// returns v unchanged.
137	func Truncate(v []float32, d int) []float32 {
138		if d <= 0 || d >= len(v) {
139			return v
140		}
141		return Normalize(v[:d])
142	}
143	
144	// Cosine is the similarity between two unit vectors, which is their dot
145	// product. It does not normalise: an embedding out of this package already
146	// is a unit vector, and quietly renormalising would hide a caller that had
147	// truncated one and not the other.
148	func Cosine(a, b []float32) float32 {
149		var sum float32
150		for i := range a {
151			sum += a[i] * b[i]
152		}
153		return sum
154	}
