func runGPU(dir string, cfg *qwen.Config, inputs, kinds []string, dim, reps, maxTokens int, prof bool, show int) {
	dev, done := openDevice()
	defer done()

	tok, err := embed.LoadTokenizer(dir)
	must(err)
	ids := make([][]int32, len(inputs))
	longest := 0
	for i, text := range inputs {
		ids[i], err = tok.Encode(text)
		must(err)
		longest = max(longest, len(ids[i]))
	}
	if maxTokens == 0 {
		maxTokens = longest
	}

	start := time.Now()
	g, err := embed.NewGPU(dev, dir, maxTokens)
	must(err)
