55	// NewEmbed loads the checkpoint. On the device that is 0.88 GB of fp16 banks
56	// staged in about 1.3 s; on the host it is 2.4 GB of fp32 and about 2 s.
57	func NewEmbed(opt EmbedOptions) (*Embed, error) {
58		if opt.ID == "" {
59			opt.ID = defaultEmbedModelID
60		}
61		if opt.MaxTokens <= 0 {
62			opt.MaxTokens = defaultEmbedTokens
63		}
64		b := &Embed{opt: opt, id: opt.ID}
65		if opt.Device == nil {
66			m, err := embed.Load(opt.Model)
67			if err != nil {
68				return nil, err
69			}
70			b.cpu = m
71			return b, nil
72		}
73		err := opt.Device.Do(func(dev *vk.Device) error {
74			g, err := embed.NewGPU(dev, opt.Model, opt.MaxTokens)
75			if err != nil {
76				return err
77			}
