106	// Embed runs every input in the request, in order.
107	//
108	// The inputs are run one at a time. That is not an oversight: the encoder's
109	// graph is one causal sequence, so two texts in one pass would need a
110	// block-diagonal mask the attention kernel does not have (EMBEDDING.md E7),
111	// and concatenating them without one would let the second text attend to the
112	// first -- a wrong answer rather than a slow one.
113	func (b *Embed) Embed(ctx context.Context, req *api.EmbeddingRequest) (*api.EmbeddingResult, error) {
114		b.mu.Lock()
115		defer b.mu.Unlock()
116		if b.gpu == nil && b.cpu == nil {
117			return nil, fmt.Errorf("backend: the embedding model is closed")
118		}
119		if req.Dimensions > embed.Dim {
120			return nil, fmt.Errorf("%w: dimensions is %d; this model produces %d",
121				api.ErrUnsupported, req.Dimensions, embed.Dim)
122		}
123	
124		res := &api.EmbeddingResult{Vectors: make([][]float32, len(req.Input))}
125		for i, text := range req.Input {
126			// The instruction is prepended here rather than by the caller
127			// because it is part of the *text* the model reads, so it has to be
128			// inside the token count the response reports.
129			if req.Instruct != "" {
130				task := req.Instruct
131				if task == "default" {
132					task = embed.DefaultTask
133				}
134				text = embed.Instruct(task, text)
135			}
136			// Cancellation is checked between inputs. Inside one there is
137			// nothing to check: a run is a submitted command buffer, and coming
138			// back from it early would leave the device mid-graph.
139			if err := ctx.Err(); err != nil {
140				return nil, err
141			}
142			ids, err := b.encode(text)
143			if err != nil {
144				return nil, err
145			}
146			var v []float32
147			if b.gpu != nil {
148				err = b.opt.Device.Do(func(*vk.Device) error {
149					var e error
150					v, e = b.gpu.EmbedIDs(ids)
151					return e
152				})
153			} else {
154				v, err = b.cpu.EmbedIDs(ids)
155			}
156			if err != nil {
157				return nil, err
158			}
159			res.Vectors[i] = embed.Truncate(v, req.Dimensions)
160			res.Usage.PromptTokens += len(ids)
161		}
162		res.Usage.TotalTokens = res.Usage.PromptTokens
163		return res, nil
164	}
