167	// and re-appends the end-of-text token, which is what HF's
168	// `truncation=True` does and what last-token pooling requires: the pooled row
169	// is the appended token's, so a truncation that dropped it would pool a
170	// different token than every other input did.
171	func (b *Embed) encode(text string) ([]int32, error) {
172		tok := b.cpuTokenizer()
173		return tok.EncodeLimit(text, b.opt.MaxTokens)
174	}
