45			vecs = make([][]float32, len(req.Input))
46			for i := range vecs {
47				vecs[i] = []float32{float32(i), 0.5, -0.5, 1}
48			}
49		}
50		return &EmbeddingResult{Vectors: vecs, Usage: Usage{PromptTokens: 7, TotalTokens: 7}}, nil
51	}
52	
53	func TestEmbeddings(t *testing.T) {
54		f := &fakeEmbedding{}
55		s := &Server{Embedding: f}
56		rec := do(t, s, jsonRequest("POST", "/v1/embeddings", EmbeddingRequest{
57			Input: StringList{"one", "two"}, Model: "text-embedding-3-small",
58		}))
59		if rec.Code != http.StatusOK {
60			t.Fatalf("status %d: %s", rec.Code, rec.Body)
61		}
62		var resp EmbeddingResponse
63		if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
64			t.Fatal(err)
65		}
66		if resp.Object != "list" || len(resp.Data) != 2 {
67			t.Fatalf("object %q, %d items", resp.Object, len(resp.Data))
68		}
69		// The response reports what ran, not what was asked for, as every other
70		// endpoint here does.
71		if resp.Model != "qwen3-embedding-0.6b" {
72			t.Errorf("model %q", resp.Model)
73		}
74		for i, item := range resp.Data {
75			if item.Object != "embedding" || item.Index != i {
76				t.Errorf("item %d: object %q index %d", i, item.Object, item.Index)
77			}
78		}
79		if resp.Usage == nil || resp.Usage.PromptTokens != 7 || resp.Usage.TotalTokens != 7 {
80			t.Errorf("usage %+v", resp.Usage)
81		}
82	}
83	
84	// A single string and an array of strings are the same request, which is the
85	// one thing about OpenAI's envelope a client is most likely to exercise both
86	// ways.
87	func TestEmbeddingsInputForms(t *testing.T) {
88		for _, body := range []string{
89			`{"input": "one"}`,
90			`{"input": ["one"]}`,
91		} {
92			f := &fakeEmbedding{}
93			rec := do(t, &Server{Embedding: f}, rawRequest("POST", "/v1/embeddings", body))
94			if rec.Code != http.StatusOK {
95				t.Fatalf("%s: status %d: %s", body, rec.Code, rec.Body)
96			}
97			if len(f.req.Input) != 1 || f.req.Input[0] != "one" {
98				t.Errorf("%s: backend saw %v", body, f.req.Input)
99			}
100		}
101	}
102	
103	// base64 is OpenAI's other encoding: little-endian float32. A client that
104	// asked for it and got JSON numbers would decode garbage, so the bytes are
105	// checked rather than the field's type.
106	func TestEmbeddingsBase64(t *testing.T) {
107		f := &fakeEmbedding{vecs: [][]float32{{1, -2, 0.25}}}
108		rec := do(t, &Server{Embedding: f}, jsonRequest("POST", "/v1/embeddings", EmbeddingRequest{
109			Input: StringList{"one"}, EncodingFormat: "base64",
110		}))
111		if rec.Code != http.StatusOK {
112			t.Fatalf("status %d: %s", rec.Code, rec.Body)
113		}
114		var resp EmbeddingResponse
115		if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
116			t.Fatal(err)
117		}
118		enc, ok := resp.Data[0].Embedding.(string)
119		if !ok {
120			t.Fatalf("embedding is %T, want a base64 string", resp.Data[0].Embedding)
121		}
122		raw, err := base64.StdEncoding.DecodeString(enc)
123		if err != nil {
124			t.Fatal(err)
125		}
126		if len(raw) != 12 {
127			t.Fatalf("%d bytes for 3 float32", len(raw))
128		}
129		for i, want := range []float32{1, -2, 0.25} {
130			got := math.Float32frombits(binary.LittleEndian.Uint32(raw[4*i:]))
131			if got != want {
132				t.Errorf("component %d is %g, want %g", i, got, want)
133			}
134		}
135	}
136	
137	// The instruction is this API's one extension, and it has to reach the
138	// backend untouched: it is the difference between a query vector and a
139	// document vector.
140	func TestEmbeddingsInstruct(t *testing.T) {
141		f := &fakeEmbedding{}
142		rec := do(t, &Server{Embedding: f}, rawRequest("POST", "/v1/embeddings",
143			`{"input": "one", "instruct": "Retrieve documents about cats", "dimensions": 32}`))
144		if rec.Code != http.StatusOK {
145			t.Fatalf("status %d: %s", rec.Code, rec.Body)
146		}
147		if f.req.Instruct != "Retrieve documents about cats" || f.req.Dimensions != 32 {
148			t.Errorf("backend saw instruct %q, dimensions %d", f.req.Instruct, f.req.Dimensions)
149		}
150	}
151	
152	func TestEmbeddingsRejects(t *testing.T) {
153		for _, c := range []struct{ name, body string }{
154			{"no input", `{}`},
155			{"empty string", `{"input": ""}`},
156			{"empty in array", `{"input": ["one", ""]}`},
157			{"bad encoding", `{"input": "one", "encoding_format": "float16"}`},
158			{"negative dimensions", `{"input": "one", "dimensions": -1}`},
159		} {
160			f := &fakeEmbedding{}
161			rec := do(t, &Server{Embedding: f}, rawRequest("POST", "/v1/embeddings", c.body))
162			if rec.Code != http.StatusBadRequest {
163				t.Errorf("%s: status %d: %s", c.name, rec.Code, rec.Body)
164			}
165			if f.req != nil {
166				t.Errorf("%s: reached the backend", c.name)
167			}
168		}
169	}
